const espera = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));

async function emSerie() {
  const a = [];
  for (const ms of [30, 20, 10]) a.push(await espera(ms, ms));
  return a.join(',');
}

async function emParalelo() {
  const a = await Promise.all([30, 20, 10].map((ms) => espera(ms, ms)));
  return a.join(',');
}

(async () => {
  console.log(await emSerie());
  console.log(await emParalelo());
})();

